describe('Payment Card Declined Error State', () => {
  beforeEach(() => {
    cy.visit('/payment');
  });

  it('should display clear error message when payment card is declined', () => {
    // Intercept the payment API call
    cy.intercept('POST', '/api/payment/process', {
      statusCode: 400,
      body: {
        error: 'Card declined',
        message: 'The card you entered was declined. Please try a different card or contact your bank.'
      }
    }).as('paymentFailed');

    // Fill in payment form
    cy.get('[data-testid="card-number-input"]').type('4111111111111111');
    cy.get('[data-testid="expiry-date-input"]').type('12/25');
    cy.get('[data-testid="cvv-input"]').type('123');

    // Submit payment
    cy.get('[data-testid="submit-payment-btn"]').click();

    // Wait for payment API response
    cy.wait('@paymentFailed');

    // Verify error message is displayed
    cy.get('[data-testid="payment-error-message"]')
      .should('be.visible')
      .should('contain', 'Card declined');

    // Verify error message contains specific text
    cy.get('[data-testid="payment-error-message"]')
      .should('contain', 'Please try a different card or contact your bank.');

    // Verify success button is disabled
    cy.get('[data-testid="success-btn"]')
      .should('be.disabled');

    // Verify retry button is visible
    cy.get('[data-testid="retry-btn"]')
      .should('be.visible');
  });

  it('should handle multiple declined attempts and show retry limit', () => {
    // Intercept the payment API call multiple times
    cy.intercept('POST', '/api/payment/process', {
      times: 3,
      statusCode: 400,
      body: {
        error: 'Card declined',
        message: 'The card you entered was declined. Please try a different card or contact your bank.'
      }
    }).as('paymentFailed');

    // Fill in payment form
    cy.get('[data-testid="card-number-input"]').type('4111111111111111');
    cy.get('[data-testid="expiry-date-input"]').type('12/25');
    cy.get('[data-testid="cvv-input"]').type('123');

    // Submit payment multiple times
    cy.get('[data-testid="submit-payment-btn"]').click();
    cy.get('[data-testid="submit-payment-btn"]').click();
    cy.get('[data-testid="submit-payment-btn"]').click();

    // Wait for payment API response
    cy.wait('@paymentFailed');

    // Verify error message is still visible after multiple attempts
    cy.get('[data-testid="payment-error-message"]')
      .should('be.visible')
      .should('contain', 'Card declined');

    // Verify retry button is still visible
    cy.get('[data-testid="retry-btn"]')
      .should('be.visible');

    // Verify retry limit is displayed
    cy.get('[data-testid="retry-limit-message"]')
      .should('be.visible')
      .should('contain', 'You have reached the maximum number of retry attempts.');

    // Verify success button remains disabled
    cy.get('[data-testid="success-btn"]')
      .should('be.disabled');
  });
});
